// Set Up Study: choose the 25 participants the agents are built from and generate the three networks.
// Everything follows from the seed, so running this again with the same seed changes nothing.
// Output: one item { summary, sim_cast: [...], sim_networks: [...] } for the upsert blocks.
// ---- lib/scoring.js ----
// Shared scoring (spliced into Code nodes by build.mjs via `// @include lib/scoring.js`).
// facet = mean of its items; a reverse item is scale_max + 1 - value; BFI-2 negative emotionality is
// reported as emotional_stability = 6 - NE. `items` are rows of the `items` table.
const FACETS = ['extraversion', 'agreeableness', 'conscientiousness', 'emotional_stability', 'openness'];
const SCALE_MAX = { bfi2: 5, mini_markers: 9 };

function toNumber(v) {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
}

function isTrue(v) {
  return v === true || v === 'true' || v === 1 || v === '1';
}

// answers: { item_key: value }. Returns { facet: mean } with null for a facet that has no answers.
function facetScores(items, instrument, answers) {
  const max = SCALE_MAX[instrument];
  const sums = {};
  for (const it of items) {
    if (it.instrument !== instrument) continue;
    const v = toNumber(answers[it.item_key]);
    if (v === null) continue;
    const scored = isTrue(it.reverse) ? max + 1 - v : v;
    (sums[it.facet] = sums[it.facet] || []).push(scored);
  }
  const out = {};
  for (const f of FACETS) out[f] = null;
  for (const [facet, vals] of Object.entries(sums)) {
    const mean = vals.reduce((a, b) => a + b, 0) / vals.length;
    if (facet === 'negative_emotionality') out.emotional_stability = 6 - mean;
    else if (FACETS.includes(facet)) out[facet] = mean;
  }
  return out;
}

function hasAllFacets(scores) {
  return FACETS.every((f) => scores[f] !== null && scores[f] !== undefined);
}

function round3(x) {
  return x === null || x === undefined ? null : Math.round(x * 1000) / 1000;
}
// ---- end lib/scoring.js ----
// ---- lib/graph.js ----
// Graph helpers for the network experiments (spliced into Code nodes via `// @include lib/graph.js`).
// A graph is n nodes (0..n-1) and a list of undirected edges [a, b] with a < b.

// Seeded random numbers (mulberry32): the same seed always gives the same sequence.
function rng(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6D2B79F5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const pick = (list, rand) => list[Math.floor(rand() * list.length)];
const edgeKey = (a, b) => (a < b ? `${a}-${b}` : `${b}-${a}`);

function adjacency(n, edges) {
  const adj = Array.from({ length: n }, () => new Set());
  for (const [a, b] of edges) { adj[a].add(b); adj[b].add(a); }
  return adj;
}

// Hop distance from `start` to every node (Infinity when unreachable).
function distances(n, edges, start) {
  const adj = adjacency(n, edges);
  const dist = Array(n).fill(Infinity);
  dist[start] = 0;
  const queue = [start];
  for (let q = 0; q < queue.length; q++) for (const nb of adj[queue[q]]) if (dist[nb] === Infinity) { dist[nb] = dist[queue[q]] + 1; queue.push(nb); }
  return dist;
}
const isConnected = (n, edges) => distances(n, edges, 0).every((d) => d < Infinity);

// Watts-Strogatz small world: a ring where everyone knows k nearest neighbours (k even), each edge
// rewired with probability beta. Redrawn until connected.
function smallWorld(n, k, beta, rand) {
  for (;;) {
    const keys = new Set();
    for (let i = 0; i < n; i++) for (let j = 1; j <= k / 2; j++) keys.add(edgeKey(i, (i + j) % n));
    for (let i = 0; i < n; i++) {
      for (let j = 1; j <= k / 2; j++) {
        if (rand() >= beta) continue;
        const free = [];
        for (let c = 0; c < n; c++) if (c !== i && !keys.has(edgeKey(i, c))) free.push(c);
        if (!free.length) continue;
        keys.delete(edgeKey(i, (i + j) % n));
        keys.add(edgeKey(i, pick(free, rand)));
      }
    }
    const edges = [...keys].map((s) => s.split('-').map(Number)).sort((x, y) => x[0] - y[0] || x[1] - y[1]);
    if (isConnected(n, edges)) return edges;
  }
}

// Barabasi-Albert preferential attachment: each new node links to m existing nodes, favouring the
// well connected. Gives a few hubs and many peripheral nodes.
function prefAttach(n, m, rand) {
  const edges = [];
  const ends = [];
  for (let i = 0; i <= m; i++) for (let j = i + 1; j <= m; j++) { edges.push([i, j]); ends.push(i, j); }
  for (let v = m + 1; v < n; v++) {
    const targets = new Set();
    while (targets.size < m) targets.add(pick(ends, rand));
    for (const t of targets) { edges.push([t, v]); ends.push(t, v); }
  }
  return edges.sort((x, y) => x[0] - y[0] || x[1] - y[1]);
}

const density = (n, edges) => (2 * edges.length) / (n * (n - 1));

// Share of connected triples that are closed (global clustering coefficient).
function clustering(n, edges) {
  const adj = adjacency(n, edges);
  let triples = 0;
  let closed = 0;
  for (let v = 0; v < n; v++) {
    const nb = [...adj[v]];
    for (let i = 0; i < nb.length; i++) for (let j = i + 1; j < nb.length; j++) { triples++; if (adj[nb[i]].has(nb[j])) closed++; }
  }
  return triples ? closed / triples : 0;
}

function degreeSd(n, edges) {
  const deg = adjacency(n, edges).map((s) => s.size);
  const m = deg.reduce((a, b) => a + b, 0) / n;
  return Math.sqrt(deg.reduce((a, d) => a + (d - m) ** 2, 0) / n);
}
// ---- end lib/graph.js ----
const N = 25;
const NAMES = ['Alex', 'Avery', 'Blake', 'Casey', 'Charlie', 'Dakota', 'Devin', 'Elliot', 'Emerson', 'Finley', 'Harper', 'Hayden', 'Jamie',
  'Jordan', 'Kai', 'Logan', 'Morgan', 'Parker', 'Quinn', 'Reese', 'Robin', 'Rowan', 'Shay', 'Skyler', 'Taylor'];
const seed = Math.floor(Number($('Set up form').first().json.Seed)) || 1;

const eligible = new Set($('Read: participants').all().map((i) => i.json).filter((p) => p && p.persona && isTrue(p.has_mini_markers)).map((p) => Number(p.participant_id)));
const people = $('Read: scores').all().map((i) => i.json)
  .filter((s) => s && s.subject === 'human_bfi2' && eligible.has(Number(s.participant_id)) && FACETS.every((f) => toNumber(s[f]) !== null))
  .map((s) => ({ participant_id: Number(s.participant_id), ...Object.fromEntries(FACETS.map((f) => [f, toNumber(s[f])])) }))
  .sort((a, b) => a.participant_id - b.participant_id);
if (people.length < N) throw new Error(`Need ${N} participants with a persona, Mini-Markers and BFI-2 scores; found ${people.length}. Run "Big Five 2 - Import Human Data" first.`);

// Span the trait range: start from the most average person, then keep adding whoever is farthest
// (in standardized trait space) from everyone already chosen.
const z = FACETS.map((f) => {
  const xs = people.map((p) => p[f]);
  const m = xs.reduce((a, b) => a + b, 0) / xs.length;
  const s = Math.sqrt(xs.reduce((a, x) => a + (x - m) ** 2, 0) / xs.length) || 1;
  return xs.map((x) => (x - m) / s);
});
const dist = (a, b) => Math.sqrt(FACETS.reduce((acc, _, k) => acc + (z[k][a] - z[k][b]) ** 2, 0));
const norm = (a) => Math.sqrt(FACETS.reduce((acc, _, k) => acc + z[k][a] ** 2, 0));
const chosen = [people.map((_, i) => i).reduce((best, i) => (norm(i) < norm(best) ? i : best), 0)];
while (chosen.length < N) {
  let best = -1;
  let bestD = -1;
  for (let i = 0; i < people.length; i++) {
    if (chosen.includes(i)) continue;
    const d = Math.min(...chosen.map((c) => dist(i, c)));
    if (d > bestD) { best = i; bestD = d; }
  }
  chosen.push(best);
}
// Shuffle, so network position does not follow the order people were picked in.
const rand = rng(seed);
for (let i = chosen.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [chosen[i], chosen[j]] = [chosen[j], chosen[i]]; }
const sim_cast = chosen.map((c, i) => ({ key: `a${String(i + 1).padStart(2, '0')}`, agent: i + 1, name: NAMES[i], ...people[c] }));

const degrees = (edges) => adjacency(N, edges).map((s) => s.size);
const farthest = (edges, from, among) => { const d = distances(N, edges, from); return among.reduce((best, i) => (d[i] > d[best] ? i : best), among[0]); };
const everyone = Array.from({ length: N }, (_, i) => i);
const network = (key, generator, edges, roles, seedNo) => ({ key, generator, nodes: N, seed: seedNo, edges: JSON.stringify(edges), roles: JSON.stringify(roles) });

const spread = smallWorld(N, 4, 0.1, rng(seed + 1));
const host = Math.floor(rng(seed + 11)() * N);
const sparse = smallWorld(N, 2, 0.1, rng(seed + 2));
const sparseHost = Math.floor(rng(seed + 12)() * N);
const hubby = prefAttach(N, 2, rng(seed + 3));
const deg = degrees(hubby);
const hub = deg.indexOf(Math.max(...deg));
const leaves = everyone.filter((i) => deg[i] === Math.min(...deg));
const sim_networks = [
  network('propagation', 'small world: 25 nodes, 4 neighbours, 10% rewired', spread, { seed: host, decoy: farthest(spread, host, everyone) }, seed + 1),
  network('structure', 'sparse small world: 25 nodes, 2 neighbours, 10% rewired', sparse, { seed: sparseHost }, seed + 2),
  network('dynamics', 'preferential attachment: 25 nodes, 2 links per new node', hubby, { hub, peripheral: farthest(hubby, hub, leaves) }, seed + 3),
];
return [{ json: { summary: `${sim_cast.length} agents, ${sim_networks.map((w) => `${w.key}: ${JSON.parse(w.edges).length} ties`).join(', ')}`, sim_cast, sim_networks } }];

// Upsert helper, one node per table and mode. build.mjs replaces Set up (the node whose single
// output item holds the staged rows under sim_cast), sim_cast (table name, also the "Read: <table>"
// node that fetched the existing rows) and new ("new" or "changed").
//  new:     staged rows whose key is not in the table yet  -> Batch Create
//  changed: existing rows whose staged values differ, as { id, ...staged } -> Update
// Values are compared loosely (Baserow returns numbers as strings; '' and null are the same).
const staged = $('Set up').first().json['sim_cast'] || [];
const existing = $('Read: sim_cast').all().map((i) => i.json).filter((r) => r && r.id !== undefined && r.key !== undefined);
const byKey = new Map(existing.map((r) => [String(r.key), r]));

const norm = (v) => {
  if (v === null || v === undefined || v === '') return '';
  if (typeof v === 'boolean') return v ? 'true' : 'false';
  if (v === 'true' || v === 'false') return v;
  const n = Number(v);
  if (typeof v === 'number' || (typeof v === 'string' && v.trim() !== '' && Number.isFinite(n))) return String(Number(n.toFixed(6)));
  return String(v).trim();
};
const differs = (row, cur) => Object.keys(row).some((k) => norm(row[k]) !== norm(cur[k]));

const out = [];
for (const row of staged) {
  const cur = byKey.get(String(row.key));
  if ('new' === 'new' && !cur) out.push({ json: row });
  if ('new' === 'changed' && cur && differs(row, cur)) out.push({ json: { id: cur.id, ...row } });
}
return out;

